var dateInput = input.get('date');
var outputFormat = input.get('outputFormat') || 'ISO';
var addDays = parseInt(input.get('addDays') || '0');
var addHours = parseInt(input.get('addHours') || '0');

if (!dateInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Date input is required');
    output.set('Result', '');
    tags.trigger('error');
} else {
    try {
        var date = new Date(dateInput);
        if (isNaN(date.getTime())) {
            throw new Error('Invalid date format');
        }

        if (addDays) date.setDate(date.getDate() + addDays);
        if (addHours) date.setHours(date.getHours() + addHours);

        function pad(n) { return n < 10 ? '0' + n : n; }

        var y = date.getFullYear();
        var m = pad(date.getMonth() + 1);
        var d = pad(date.getDate());
        var h = pad(date.getHours());
        var min = pad(date.getMinutes());
        var s = pad(date.getSeconds());

        var result = '';
        switch (outputFormat) {
            case 'ISO': result = date.toISOString(); break;
            case 'UTC': result = date.toUTCString(); break;
            case 'YYYY-MM-DD': result = y + '-' + m + '-' + d; break;
            case 'DD/MM/YYYY': result = d + '/' + m + '/' + y; break;
            case 'MM/DD/YYYY': result = m + '/' + d + '/' + y; break;
            case 'YYYY-MM-DD HH:mm:ss': result = y + '-' + m + '-' + d + ' ' + h + ':' + min + ':' + s; break;
            case 'Unix': result = Math.floor(date.getTime() / 1000).toString(); break;
            case 'UnixMs': result = date.getTime().toString(); break;
            default: result = date.toISOString();
        }

        output.set('Result', result);
        output.set('ISO', date.toISOString());
        output.set('Unix', Math.floor(date.getTime() / 1000));
        output.set('Year', y);
        output.set('Month', date.getMonth() + 1);
        output.set('Day', date.getDate());
        output.set('DayOfWeek', date.getDay());
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Formatted date: ' + result);
        tags.trigger('success');

    } catch (ex) {
        log.error('Date format failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('Result', '');
        tags.trigger('error');
    }
}
